function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments must be lists of the same length.';
  if (operations[0] !== 'Trie' || !Array.isArray(args[0]) || args[0].length !== 0) return 'Start with Trie and no arguments.';
  if (operations.length - 1 > 30000) return 'At most 3 * 10^4 calls in total.';
  const known = ['insert', 'countWordsEqualTo', 'countWordsStartingWith', 'erase'];
  const stored = new Map();
  for (let i = 1; i < operations.length; i++) {
    const call = args[i];
    if (!known.includes(operations[i])) return 'Only insert, countWordsEqualTo, countWordsStartingWith and erase can follow the constructor.';
    if (!Array.isArray(call) || call.length !== 1 || typeof call[0] !== 'string' || !/^[a-z]{1,2000}$/.test(call[0])) return `${operations[i]} needs one string of 1 to 2000 lowercase letters.`;
    const word = call[0];
    if (operations[i] === 'insert') stored.set(word, (stored.get(word) ?? 0) + 1);
    if (operations[i] === 'erase') {
      if (!stored.get(word)) return `erase("${word.slice(0, 20)}") is called when that word is not stored.`;
      stored.set(word, stored.get(word) - 1);
    }
  }
  return null;
}

