class Trie {
  // A multiset of whole words; prefix queries scan every stored word.
  constructor() {
    this.copies = new Map();
  }
  insert(word) {
    this.copies.set(word, (this.copies.get(word) || 0) + 1);
  }
  countWordsEqualTo(word) {
    return this.copies.get(word) || 0;
  }
  countWordsStartingWith(prefix) {
    let total = 0;
    for (const [word, count] of this.copies) if (word.startsWith(prefix)) total += count;
    return total;
  }
  erase(word) {
    this.copies.set(word, this.copies.get(word) - 1);
  }
}

