function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  const letters = large ? (rand() < 0.5 ? 'abc' : 'abcdefghij') : 'ab';
  const calls = large ? 499 : 1 + pick(12);
  const randomWord = () => {
    const length = large ? (rand() < 0.03 ? 100 + pick(400) : 1 + pick(12)) : 1 + pick(3);
    let word = '';
    for (let k = 0; k < length; k++) word += letters[pick(letters.length)];
    return word;
  };
  const stored = [];
  const operations = ['Trie'];
  const args = [[]];
  for (let c = 0; c < calls; c++) {
    const roll = rand();
    if (roll < 0.35 || stored.length === 0 && roll < 0.5) {
      // Reuse a stored word sometimes so duplicates appear.
      const word = stored.length && rand() < 0.3 ? stored[pick(stored.length)] : randomWord();
      stored.push(word);
      operations.push('insert');
      args.push([word]);
    } else if (roll < 0.5) {
      const at = pick(stored.length);
      operations.push('erase');
      args.push([stored[at]]);
      stored.splice(at, 1);
    } else {
      let text;
      if (stored.length && rand() < 0.7) {
        const word = stored[pick(stored.length)];
        text = word.slice(0, 1 + pick(word.length));
      } else text = randomWord();
      operations.push(rand() < 0.5 ? 'countWordsEqualTo' : 'countWordsStartingWith');
      args.push([text]);
    }
  }
  return [operations, args];
}
